package com.slotix.reservationcore.availability; import jakarta.persistence.*; import java.time.*; import java.util.*;
@Entity @Table(name="resource_blocks") public class ResourceBlock { @Id @GeneratedValue private UUID id; @Column(name="company_id") private UUID companyId; @Column(name="resource_id") private UUID resourceId; @Column(name="start_at") private Instant startAt; @Column(name="end_at") private Instant endAt; private String reason; @Enumerated(EnumType.STRING) @Column(name="block_type") private ResourceBlockType blockType; @Column(name="created_at") private Instant createdAt; @Column(name="updated_at") private Instant updatedAt; @Column(name="deleted_at") private Instant deletedAt; protected ResourceBlock(){} public static ResourceBlock create(UUID c,UUID r,Instant s,Instant e,String reason,ResourceBlockType t){ResourceBlock b=new ResourceBlock();b.companyId=c;b.resourceId=r;b.startAt=s;b.endAt=e;b.reason=reason;b.blockType=t;b.createdAt=Instant.now();b.updatedAt=b.createdAt;return b;} public UUID getId(){return id;} public Instant getStartAt(){return startAt;} public Instant getEndAt(){return endAt;} public String getReason(){return reason;} public ResourceBlockType getBlockType(){return blockType;} }
